// Pengganti BOT_START_TIME di bot lama: pesan yang datang terlambat (mis. dikirim
// ulang WAHA saat sesi tersambung kembali) diabaikan supaya tidak dibalas ulang.
const payload = $input.first().json.body.payload;
const umurDetik = Math.floor(Date.now() / 1000) - (payload.timestamp || 0);
if (umurDetik > 5 * 60) return [];
return [{ json: { chatId: payload.from, messageId: payload.id, body: payload.body || '' } }];

parameters.query:
select
  (select case when c.state_updated_at > now() - interval '30 minutes' then c.state end
     from bot.conversations c where c.chat_id = $1) as state,
  coalesce((select c.history from bot.conversations c where c.chat_id = $1), '{}') as history,
  (select json_agg(json_build_object('name', b.name, 'specialization', b.specialization) order by b.created_at)
     from public.barbers b where b.status = 'active' and not b.archived) as barbers,
  (select json_agg(json_build_object('name', s.name, 'price', s.price, 'duration_minutes', s.duration_minutes) order by s.created_at)
     from public.services s where not s.archived) as services,
  (select json_build_object('open_hour', h.open_hour, 'close_hour', h.close_hour, 'shop_name', h.shop_name)
     from public.business_hours h limit 1) as hours,
  (select json_agg(json_build_object('name', b.name, 'besok', t.off_date > (now() at time zone 'Asia/Jakarta')::date))
     from public.barber_time_off t join public.barbers b on b.id = t.barber_id
     where t.off_date in ((now() at time zone 'Asia/Jakarta')::date, (now() at time zone 'Asia/Jakarta')::date + 1)) as time_off

parameters.jsCode:
// Port getBusinessContext() (server/services/bookingDomain.js) dan prompt
// parseBookingMessage() (server/services/gemini.js). Teks prompt disalin apa
// adanya; ubah di sini kalau prompt bot perlu diubah.
const pesan = $('Siapkan Pesan').first().json;
const data = $input.first().json;
const text = pesan.body;

// Aturan pesan pendek dari index.js: abaikan pesan < 5 karakter kecuali
// sedang ada sesi booking atau pesannya sapaan.
const GREETING_WORDS = ['halo', 'hallo', 'hai', 'hi', 'hey', 'min', 'bang', 'bg', 'kak', 'permisi', 'pagi', 'siang', 'sore', 'malam'];
const bodyNormalized = text.trim().toLowerCase();
const isGreeting = GREETING_WORDS.some(g => bodyNormalized === g || bodyNormalized.startsWith(g + ' ') || bodyNormalized.startsWith(g + ','));
if (!text || (text.trim().length < 5 && !data.state && !isGreeting)) return [];

const shopName = (data.hours && data.hours.shop_name) || 'BarberFlow';
let businessContext = '';
if (data.hours) {
  businessContext += `Jam operasional: ${String(data.hours.open_hour).padStart(2, '0')}:00 - ${String(data.hours.close_hour).padStart(2, '0')}:00 setiap hari.\n`;
}
if (data.barbers && data.barbers.length > 0) {
  businessContext += `Kapster aktif: ${data.barbers.map(b => `${b.name} (${b.specialization || 'Umum'})`).join(', ')}.\n`;
}
if (data.services && data.services.length > 0) {
  businessContext += `Layanan: ${data.services.map(s => `${s.name} (Rp${Number(s.price).toLocaleString('id-ID')}, ${s.duration_minutes} menit)`).join(', ')}.`;
}
if (data.time_off && data.time_off.length > 0) {
  businessContext += `\nInfo cuti: ${data.time_off.map(t => `${t.name} libur pada ${t.besok ? 'besok' : 'hari ini'}`).join(', ')}.`;
} else {
  businessContext += `\nInfo cuti: Tidak ada kapster yang libur hari ini atau besok (semua kapster aktif tersedia sesuai jam operasional).`;
}

const SYSTEM_PROMPT = `TUGAS:
Analisis pesan pelanggan dan kembalikan HANYA objek JSON tanpa teks tambahan apapun, tanpa markdown, tanpa penjelasan. Hanya JSON murni.

FORMAT OUTPUT WAJIB:
{
  "nama": string atau null,
  "hari": string atau null,
  "jam": string atau null,
  "servis": string atau null,
  "kapster": string atau null,
  "isBookingIntent": boolean,
  "naturalReply": string atau null
}

ATURAN KRITIS — BACA DENGAN SEKSAMA:

1. FIELD "jam": ISI HANYA jika pelanggan menyebutkan jam SECARA EKSPLISIT dengan angka.
   - "jam 2 siang" -> "14:00"
   - "jam 10" -> "10:00"
   - "pagi" / "sore" / "malam" / "besok" / "nanti" -> JAM WAJIB null, JANGAN ditebak
   - Tidak ada penyebutan jam sama sekali -> null

2. FIELD "hari": WAJIB dinormalisasi ke nama hari dalam bahasa Indonesia atau kata ganti mutlak.
   - HANYA BOLEH DIISI: "hari ini", "besok", "lusa", "Senin", "Selasa", "Rabu", "Kamis", "Jumat", "Sabtu", "Minggu".
   - Jika pelanggan merujuk pada histori chat (misal: "hari yang sama", "sama kayak tadi"), BACA histori chat untuk menyimpulkan harinya (misal: "Selasa"). JANGAN PERNAH mengisi dengan frasa "hari yang sama".
   - Jika pelanggan menyebut "minggu depan" -> null (terlalu ambigu, butuh tanggal pasti).
   - Jika harinya tidak jelas dan tidak bisa disimpulkan dari histori -> null.

3. FIELD "isBookingIntent":
   - Nilai isBookingIntent berdasarkan KEPASTIAN NIAT pelanggan, bukan sekadar ada tidaknya kata booking/jadwal. Tanyakan pada dirimu: 'apakah pelanggan ini sudah siap menentukan waktu/layanan untuk booking sekarang, atau dia masih tahap mengumpulkan informasi sebelum memutuskan?' Kalau pelanggan masih dalam tahap bertanya-tanya (menanyakan ketersediaan, jadwal kapster tertentu, harga, jam buka) dan belum menyatakan kesiapan untuk booking pada waktu tertentu, set isBookingIntent: false dan jawab pertanyaannya secara natural di naturalReply. Gunakan penilaian ini secara fleksibel sesuai konteks kalimat, bukan mencocokkan kata per kata.
   - Catatan: field nama/hari/jam/servis TETAP diisi jika informasi tersebut ada di pesan, terlepas dari nilai isBookingIntent. Sistem yang memanggil API ini yang memutuskan apakah field tersebut relevan berdasarkan konteks percakapan.

4. FIELD "nama": Cari nama pelanggan jika disebutkan. Sering kali pelanggan tidak menyebut nama -> null.

5. FIELD "servis": Cari jenis servis jika disebutkan (potong, cukur, creambath, dll). Normalisasi ke bahasa Indonesia yang jelas.

6. FIELD "kapster": Cari nama kapster/barber yang diminta jika disebutkan (misal: "dengan bg alex", "sama kenji"). Jika tidak disebut, WAJIB null.

7. Tangani bahasa campur Indonesia-Inggris secara natural. Contoh: "book dong bro, sabtu jam 3 sore" adalah pesan booking yang valid.

CONTOH INPUT-OUTPUT:

Input: "bang mau booking sabtu jam 2 siang, potong doang"
Output: {"nama":null,"hari":"Sabtu","jam":"14:00","servis":"Potong","kapster":null,"isBookingIntent":true,"naturalReply":null}

Input: "besok bisa gak? gua si Reza, mau cukur sama creambath dengan marcus"
Output: {"nama":"Reza","hari":"besok","jam":null,"servis":"Cukur + Creambath","kapster":"Marcus","isBookingIntent":true,"naturalReply":null}

Input: "kak mau tanya bang kenji besok ada jadwal kosong nggak ya?"
Output: {"nama":null,"hari":"besok","jam":null,"servis":null,"kapster":"Kenji","isBookingIntent":false,"naturalReply":"Halo Kak, Kapster Kenji besok masih memiliki beberapa slot kosong. Boleh diinformasikan rencana kedatangannya jam berapa agar dapat kami cek slot yang tepat?"}

Input: "pangkas aja"
Output: {"nama":null,"hari":null,"jam":null,"servis":"Potong","kapster":null,"isBookingIntent":false,"naturalReply":null}

Input: "buka jam berapa bang?"
Output: {"nama":null,"hari":null,"jam":null,"servis":null,"kapster":null,"isBookingIntent":false,"naturalReply":"Halo Kak, kami buka setiap hari dari jam 9 pagi hingga 8 malam. Apakah ada hal lain yang ingin ditanyakan, atau Kakak ingin langsung melakukan booking?"}

Input: "ok makasih"
Output: {"nama":null,"hari":null,"jam":null,"servis":null,"kapster":null,"isBookingIntent":false,"naturalReply":"Sama-sama, Kak. Kami tunggu kedatangannya."}`;

const dynamicInstruction = `Kamu adalah asisten WhatsApp untuk barbershop bernama ${shopName}. Info bisnis saat ini:
${businessContext || 'Belum ada info spesifik.'}

Tugasmu:
- Jika pesan customer adalah niat booking (isBookingIntent true), field naturalReply diisi null -- proses booking akan ditangani terpisah oleh sistem lain.
- Jika BUKAN niat booking (sapaan seperti "halo", pertanyaan seperti "jam berapa buka", "kapster siapa aja", "harga cukur berapa", atau obrolan di luar topik), balas secara natural dan ramah di field naturalReply berdasarkan info bisnis di atas. JANGAN mengarang info yang tidak ada di konteks -- kalau tidak tahu jawabannya, jujur bilang tidak punya info itu dan arahkan customer hubungi barbershop langsung.
- Kalau ada nama kapster disebut customer, cek kecocokannya dengan daftar 'Kapster aktif' di atas secara wajar (termasuk toleransi typo/panggilan akrab seperti 'bang', 'kak'). Kalau memang tidak cocok dengan siapapun di daftar, sampaikan dengan natural bahwa kamu tidak menemukan kapster tersebut, lalu sebutkan siapa saja yang tersedia -- jangan kaku menyalahkan, cukup informasikan dengan ramah.
- Jika pesan di luar topik barbershop sama sekali (curhat, obrolan random, tidak nyambung), balas singkat dan ramah, lalu arahkan halus kembali ke topik booking/layanan barbershop. Jangan kaku, jangan template baku berulang -- variasikan gaya bicara secara natural.
- naturalReply harus menggunakan Bahasa Indonesia yang profesional, sopan, dan mudah dibaca, layaknya admin barbershop yang ramah namun tetap menjaga kesan profesional. Hindari singkatan tidak baku (misalnya "udah", "nggak", "gitu", "kayak") dan jangan gunakan emotikon.
- Jika customer menanyakan atau membantah data yang sudah disebutkan sebelumnya di percakapan ini (misalnya nama, hari, jam, atau layanan), JANGAN langsung menyetujui klaim baru dari customer begitu saja. Cek dulu RIWAYAT PERCAKAPAN di bawah untuk memverifikasi fakta yang sebenarnya. Jika riwayat percakapan menunjukkan data yang berbeda dari klaim customer, sampaikan dengan sopan data yang sebenarnya sesuai riwayat tersebut. JANGAN PERNAH mengarang klaim seolah-olah kamu baru saja memeriksa sistem/database -- kamu tidak punya akses ke sistem tersebut, satu-satunya sumber fakta yang kamu punya adalah riwayat percakapan ini.

`;

const historyStr = (data.history || []).join('\n');
const historyInjection = historyStr ? `\n\n=== RIWAYAT PERCAKAPAN TERAKHIR ===\n${historyStr}` : '';
const prompt = dynamicInstruction + SYSTEM_PROMPT + historyInjection + '\n\n=== PESAN SAAT INI ===\nCustomer: "' + text + '"\nOutput:';

// Pesan panjang langsung mulai dari model yang lebih kuat, sama seperti getStartingIndex().
const MODEL_CHAIN = ['gemini-3.1-flash-lite', 'gemini-3.5-flash-lite', 'gemini-3.6-flash', 'gemini-3.5-flash'];
const models = MODEL_CHAIN.slice(text.length > 80 ? 2 : 0).map(m => 'models/' + m);

return [{ json: { prompt, models } }];

// Model kadang tetap membungkus JSON dengan blok markdown; JSON tidak valid = coba model berikutnya.
const parts = ($input.first().json.content && $input.first().json.content.parts) || [];
const raw = parts.map(p => p.text || '').join('').trim().replace(/^```(?:json)?\s*/, '').replace(/```\s*$/, '');
try {
  return [{ json: { ok: true, parsed: JSON.parse(raw.trim()) } }];
} catch (err) {
  return [{ json: { ok: false, alasan: err.message } }];
}

// Port percabangan message handler di server/index.js. Output `action`:
// balas (kirim `text`), ringkasan (cek slot lalu kirim ringkasan),
// konfirmasi (simpan booking), diam (tidak membalas). `state` = state
// percakapan yang disimpan untuk balas/diam.
const pesan = $('Siapkan Pesan').first().json;
const stateTersimpan = $('Muat Konteks').first().json.state;
const nomor = $('Cari Nomor Asli').first().json.pn || pesan.chatId;
const parsed = $input.first().json.parsed;
const text = pesan.body;
const lower = text.toLowerCase();

// Termasuk salah ketik/singkatan umum ("hri ini", "bsk") supaya hari yang sudah dinormalisasi model tidak dibuang.
const DAY_KEYWORDS = ['besok', 'lusa', 'hari ini', 'senin', 'selasa', 'rabu', 'kamis', 'jumat', 'sabtu', 'minggu', 'hri ini', 'hr ini', 'bsk', 'besuk', "jum'at", 'senen', 'rebo'];
const NEW_BOOKING_KEYWORDS = ['book lagi', 'booking lagi', 'booking baru', 'pesan lagi', 'pesen lagi', 'reservasi lagi', 'reservasi baru'];
const KONFIRMASI_WORDS = ['ya', 'iya', 'benar', 'yes', 'oke', 'ok', 'betul', 'sip', 'siap'];

const dasar = { chatId: pesan.chatId, messageId: pesan.messageId, body: text, phone: nomor.replace(/@.*$/, '') };
const hasil = (json) => [{ json: { ...dasar, ...json } }];

// Pelanggan eksplisit minta booking baru: buang sesi lama supaya jam/servis/kapster lama tidak terbawa.
let state = stateTersimpan;
if (state && NEW_BOOKING_KEYWORDS.some(k => lower.includes(k))) state = null;

const menyebutHari = DAY_KEYWORDS.some(k => lower.includes(k));

// Pertanyaan di tengah sesi booking dijawab natural. Field yang sudah tercatat sengaja
// tidak ditimpa (insiden: nama tertimpa dari pertanyaan), tapi field yang masih kosong
// boleh dilengkapi dari pesan ini. Kapster tidak ikut: pertanyaan sering menyebut nama
// kapster tanpa berarti memilihnya.
if (!parsed.isBookingIntent && parsed.naturalReply && state) {
  const dilengkapi = { ...state, awaitingConfirmation: false };
  for (const f of ['nama', 'jam', 'servis']) {
    if (!dilengkapi[f] && parsed[f]) dilengkapi[f] = parsed[f];
  }
  if (!dilengkapi.hari && parsed.hari && menyebutHari) dilengkapi.hari = parsed.hari;
  return hasil({ action: 'balas', text: parsed.naturalReply, state: dilengkapi });
}

if (!(parsed.isBookingIntent || state)) {
  return parsed.naturalReply
    ? hasil({ action: 'balas', text: parsed.naturalReply, state })
    : hasil({ action: 'diam', state });
}

const old = state || { nama: null, hari: null, jam: null, servis: null, kapster: null };
const merged = {
  nama: parsed.nama ?? old.nama,
  // Guard halusinasi hari: nilai dari model hanya dipercaya kalau pesan menyebut kata hari.
  hari: menyebutHari ? (parsed.hari ?? old.hari) : old.hari,
  jam: parsed.jam ?? old.jam,
  servis: parsed.servis ?? old.servis,
  kapster: parsed.kapster ?? old.kapster
};

const missing = [];
if (!merged.hari) missing.push('hari yang diinginkan');
if (!merged.jam) missing.push('jam yang diinginkan');
if (!merged.servis) missing.push('jenis layanan yang diinginkan (misalnya: cukur, creambath)');
if (!merged.nama) missing.push('nama untuk booking');

if (missing.length > 0) {
  const known = [];
  if (merged.hari) known.push(`hari ${merged.hari}`);
  if (merged.jam) known.push(`jam ${merged.jam}`);
  if (merged.servis) known.push(`layanan ${merged.servis}`);
  if (merged.nama) known.push(`atas nama ${merged.nama}`);
  const intro = known.length > 0 ? `Baik, untuk ${known.join(', ')}.` : `Halo, Kak. Untuk booking jadwal,`;
  const missingStr = missing.length > 1
    ? missing.slice(0, -1).join(', ') + ', dan ' + missing[missing.length - 1]
    : missing[0];
  return hasil({ action: 'balas', text: `${intro} Mohon informasikan ${missingStr}.`, state: { ...merged, awaitingConfirmation: false } });
}

const t = text.trim().toLowerCase();
const isKonfirmasi = KONFIRMASI_WORDS.some(w => t === w || t.startsWith(w + ' ') || t.endsWith(' ' + w) || t.includes(' ' + w + ' '));
if (old.awaitingConfirmation === true && isKonfirmasi) {
  // Guard halusinasi kapster: pakai kapster yang sudah disetujui pelanggan, bukan hasil parsing "ya".
  return hasil({ action: 'konfirmasi', merged, kapsterDisetujui: old.kapster });
}

// Belum pernah minta konfirmasi, atau pesan ini koreksi: cek slot ulang lalu kirim ringkasan.
return hasil({ action: 'ringkasan', merged });

// Port presentBookingSummary() di server/index.js.
const m = $('Tentukan Langkah').first().json.merged;
const { slot, jam_lain } = $input.first().json;
if (!slot.available) {
  return [{ json: { text: slot.message, state: { ...m, jam: null, kapster: null, awaitingConfirmation: false } } }];
}
const peringatan = jam_lain ? `Perlu diketahui, Anda sudah memiliki booking pada jam ${jam_lain} di hari yang sama. ` : '';
return [{ json: {
  text: `${peringatan}Baik, berikut ringkasan booking Anda: hari ${m.hari}, jam ${m.jam}, layanan ${m.servis} dengan kapster *${slot.barber}*, atas nama ${m.nama}. Apakah data tersebut sudah benar? Silakan balas "ya" untuk konfirmasi.`,
  state: { ...m, kapster: slot.barber, awaitingConfirmation: true }
} }];

// Port cabang konfirmasi di server/index.js setelah cek slot + insert.
const m = $('Tentukan Langkah').first().json.merged;
const hasil = $input.first().json.hasil;
if (!hasil.available) {
  return [{ json: { jalur: 'balas', text: `Mohon maaf, Kak, jadwal tersebut baru saja diambil oleh pelanggan lain. ${hasil.message}`, state: { ...m, jam: null, kapster: null, awaitingConfirmation: false } } }];
}
if (hasil.dp_amount == null) {
  // Harga layanan tidak ditemukan: booking tetap tersimpan tanpa DP.
  return [{ json: { jalur: 'balas', text: `Baik, Kak. Booking sudah lengkap:\n\nHari: ${m.hari}\nJam: ${m.jam}\nServis: ${m.servis}\nKapster: ${hasil.barber}\nNama: ${m.nama}\n\nTerima kasih, kami tunggu kedatangannya.`, state: null } }];
}
const dp = Number(hasil.dp_amount);
return [{ json: {
  jalur: 'dp',
  request_id: hasil.request_id,
  reference_id: hasil.reference_id,
  dp_amount: dp,
  text: `Booking hampir selesai, Kak. Silakan bayar DP sebesar Rp${dp.toLocaleString('id-ID')} (50% dari total) melalui QRIS di atas, dapat dipindai menggunakan e-wallet atau m-banking apa pun. Slot ditahan selama 30 menit; apabila melewati batas waktu tersebut, booking akan otomatis dibatalkan dan perlu dilakukan booking ulang.`
} }];

parameters.query:
with qr as (
  update public.whatsapp_requests set xendit_qr_id = $1 where id = $2::uuid returning id
), sesi as (
  update bot.conversations set state = null, state_updated_at = now(), updated_at = now() where chat_id = $3
)
select (select count(*) from qr) as qr_tersimpan
